// Only internal CMS links may replace a local film or category URL.
func safeSiteLink(raw string) string {
	raw = strings.TrimSpace(raw)
	if strings.ContainsAny(raw, "\\\r\n") {
		return ""
	}
	address, err := url.Parse(raw)
	if err != nil || address.Scheme != "" || address.Host != "" || address.User != nil || strings.ContainsAny(address.Path, "\\\r\n\x00") || path.Clean(address.Path) != address.Path || !(address.Path == "/suxinvideo" || strings.HasPrefix(address.Path, "/suxinvideo/")) {
		return ""
	}
	return raw
}

func siteVodURL(value any) string {
	film := gconv.Map(value)
	if link := safeSiteLink(gconv.String(film["link"])); link != "" {
		return link
	}
	if id := gconv.Int64(film["id"]); id > 0 {
		return "/suxinvideo/detail?id=" + strconv.FormatInt(id, 10)
	}
	return "/suxinvideo"
}

func siteNavURL(value any) string {
	item := gconv.Map(value)
	if link := safeSiteLink(gconv.String(item["url"])); link != "" {
		return link
	}
	return "/suxinvideo/type?id=" + strconv.FormatInt(gconv.Int64(item["id"]), 10)
}
